#include <iostream>
int main() {
    double floating_value = 3.14159;
    int integer_value = static_cast<int>(floating_value); // converts double to int with truncation
    bool bool_value = static_cast<bool>(integer_value); // converts int to bool
    double converted_back = static_cast<double>(integer_value); // int back to double
    std::cout << "Original double: " << floating_value << '\n';
    std::cout << "Converted to int (truncated): " << integer_value << '\n';
    std::cout << "Int to bool: " << bool_value << '\n';
    std::cout << "Int back to double: " << converted_back << '\n';
    return 0;
}
